    JPanel page(String title,String subtitle){JPanel p=new JPanel(new BorderLayout(0,16));p.setBackground(BG);p.setBorder(new EmptyBorder(22,28,24,28));JPanel h=new JPanel(new GridLayout(0,1,0,6));h.setOpaque(false);JLabel t=new JLabel(title);t.setFont(new Font("SansSerif",Font.BOLD,24));t.setForeground(WHITE);JLabel s=new JLabel(subtitle);s.setForeground(MUTED);h.add(t);h.add(s);p.add(h,BorderLayout.NORTH);return p;}
